def gercek_embedding_raporu(metin):
    if not isinstance(metin, str) or not metin.strip():
        raise ValueError("boş olmayan metin gerekli")
    tok, model, _ = ai_lab.dil_modeli()
    ids = tok(metin, add_special_tokens=False)["input_ids"]
